"""Offline voice assistant — predefined messages only, no LLM.

Priority: pyttsx3 (offline TTS) -> espeak / espeak-ng on the command line
-> silent fallback that logs the message. A system with no audio hardware
and no TTS installed still works: every message is printed and queued, so
the dashboard and logs always show what *would* have been spoken.
"""
from __future__ import annotations

import logging
import shutil
import subprocess
from collections import deque
from typing import Optional

logger = logging.getLogger("bas_har.voice")

# Predefined messages only. Nothing here is generated by a model.
MESSAGES = {
    "step_completed": "Step completed. {next_step}",
    "next_step": "Next, {next_step}",
    "skipped": "Warning! Step {missed} was skipped. {recovery}",
    "wrong_order": "Warning! That step is out of order. {recovery}",
    "unknown": "Warning! Unrecognised action. {recovery}",
    "incomplete": "Warning! The step was not finished. Please repeat it.",
    "experiment_complete": "Experiment complete. All steps finished. Log saved.",
    "experiment_start": "Experiment started. First, open the main box.",
    "held": "Uncertain reading. Holding that step for confirmation.",
}


class VoiceAssistant:
    """Offline TTS with a plain-text speech queue."""

    def __init__(self, enabled: bool = True, rate: int = 175) -> None:
        self.enabled = enabled
        self.queue: deque[str] = deque()
        self.spoken: list[str] = []  # every message, spoken or logged
        self.backend = "none"
        self._engine = None
        if not enabled:
            return
        try:
            import pyttsx3  # type: ignore

            self._engine = pyttsx3.init()
            self._engine.setProperty("rate", rate)
            self.backend = "pyttsx3"
        except Exception:
            if shutil.which("espeak-ng") or shutil.which("espeak"):
                self.backend = "espeak"

    def _speak_now(self, text: str) -> None:
        if self.backend == "pyttsx3" and self._engine is not None:
            try:
                self._engine.say(text)
                self._engine.runAndWait()
                return
            except Exception as exc:
                logger.warning("pyttsx3 failed (%s); falling back to log", exc)
        if self.backend == "espeak":
            cmd = shutil.which("espeak-ng") or shutil.which("espeak")
            try:
                subprocess.run([cmd, text], check=False,
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                return
            except Exception as exc:
                logger.warning("espeak failed (%s); falling back to log", exc)
        logger.info("[voice] %s", text)

    def say(self, text: str) -> str:
        """Speak (or log) a message. Returns the message text."""
        self.spoken.append(text)
        self.queue.append(text)
        print(f"[VOICE] {text}")
        if self.enabled:
            self._speak_now(text)
        return text

    def say_key(self, key: str, **kwargs: str) -> str:
        template = MESSAGES.get(key, "{message}")
        return self.say(template.format(**kwargs, message=kwargs.get("message", "")))

    def drain(self) -> list[str]:
        """Return and clear queued messages (used by the dashboard/API)."""
        out = list(self.queue)
        self.queue.clear()
        return out
